using System;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Text;
public partial class TV {
 public static string AiServiceError(int code,string detail){if(code==401)return "API Key 无效或已被撤销，请配置自己的 API Key。";if(code==402||code==403&&(detail??"").IndexOf("budget",StringComparison.OrdinalIgnoreCase)>=0)return "API 额度不足或共享额度已用完，请配置自己的 API Key；不会切换到付费模型。";if(code==429)return "免费接口限流或今日额度已用完，请稍后再试，或配置自己的 API Key。";if(code==403)return "API 访问被拒绝，请检查账户权限或配置自己的 API。";if(code==404||code==503)return "当前没有满足要求的可用模型，请稍后重试或配置自己的 API。";return "AI 服务暂不可用（"+code+"），请稍后重试或检查自己的接口配置。";}
 static object AiValue(Dictionary<string,object> obj,string name){object v;return obj!=null&&obj.TryGetValue(name,out v)?v:null;}
 static object AdviceRoot(object value){var d=value as Dictionary<string,object>;if(d!=null){foreach(string k in new[]{"suggestions","recommendations","items","apps","results"}){object a;if(d.TryGetValue(k,out a)&&a is IList)return a;}}return value is IList?value:null;}
 static object AdviceDocument(string text,JavaScriptSerializer json){text=text.Trim().TrimStart('\uFEFF');try{var direct=AdviceRoot(json.DeserializeObject(text));if(direct!=null)return direct;}catch{}for(int start=0;start<text.Length;start++){if(text[start]!='['&&text[start]!='{')continue;var stack=new Stack<char>();bool quoted=false,escape=false;for(int i=start;i<text.Length;i++){char c=text[i];if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;continue;}if(c=='"'){quoted=true;continue;}if(c=='['||c=='{')stack.Push(c);else if(c==']'||c=='}'){if(stack.Count==0)break;char open=stack.Pop();if(c==']'&&open!='['||c=='}'&&open!='{')break;if(stack.Count==0){try{var a=AdviceRoot(json.DeserializeObject(text.Substring(start,i-start+1)));if(a!=null)return a;}catch{}break;}}}}return null;}
 public static List<Dictionary<string,string>> ParseAiRows(string response){var json=new JavaScriptSerializer{MaxJsonLength=8000000};Dictionary<string,object> obj;try{obj=json.Deserialize<Dictionary<string,object>>(response.TrimStart('\uFEFF'));}catch{throw new Exception("AI 服务未返回有效 JSON 响应，请检查接口地址。");}var error=AiValue(obj,"error") as Dictionary<string,object>;if(error!=null){int code;int.TryParse(Convert.ToString(AiValue(error,"code")),out code);throw new Exception(AiServiceError(code,Convert.ToString(AiValue(error,"message"))));}var choices=AiValue(obj,"choices") as IList;if(choices==null||choices.Count==0)throw new Exception("AI 未返回建议，当前模型可能不可用，请稍后重试。");var choice=choices[0] as Dictionary<string,object>;string finish=Convert.ToString(AiValue(choice,"finish_reason"));if(finish=="length")throw new Exception("AI 输出被长度限制截断，请减少本批应用数量后重试。");if(finish=="content_filter")throw new Exception("模型拒绝生成本次分析，请换模型或使用自动分类。");var message=AiValue(choice,"message") as Dictionary<string,object>;if(!string.IsNullOrEmpty(Convert.ToString(AiValue(message,"refusal"))))throw new Exception("模型拒绝生成本次分析，请使用其他模型。");object content=AiValue(message,"content");string text=content as string;var blocks=content as IList;if(blocks!=null){var sb=new StringBuilder();foreach(var b in blocks){var block=b as Dictionary<string,object>;if(Convert.ToString(AiValue(block,"type"))=="text")sb.Append(Convert.ToString(AiValue(block,"text")));}text=sb.ToString();}if(string.IsNullOrWhiteSpace(text))throw new Exception("AI 没有返回正文，可能只生成了推理内容，请换模型或稍后重试。");var list=AdviceDocument(text,json) as IList;if(list==null)throw new Exception("AI 未按约定返回建议清单，已保持谨慎状态；请重试或更换模型。");var rows=new List<Dictionary<string,string>>();foreach(var item in list){var d=item as Dictionary<string,object>;if(d==null)continue;string id=Convert.ToString(AiValue(d,"id")??AiValue(d,"Id")??AiValue(d,"packageName")),risk=Convert.ToString(AiValue(d,"risk")??AiValue(d,"Risk")).ToLowerInvariant(),reason=Convert.ToString(AiValue(d,"reason")??AiValue(d,"Reason"));if(id!="android"&&!System.Text.RegularExpressions.Regex.IsMatch(id??"",@"^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$"))continue;if(risk!="low"&&risk!="high"&&risk!="unknown"&&risk!="caution")risk="unknown";rows.Add(new Dictionary<string,string>{{"id",id},{"risk",risk},{"reason",string.IsNullOrWhiteSpace(reason)?"模型未提供充分依据，请谨慎处理":reason.Substring(0,Math.Min(600,reason.Length))}});}if(rows.Count==0)throw new Exception("AI 返回的清单没有有效包名，未采用建议。");return rows;}
 void ApplyParsedAiResponse(string response,HashSet<string> allowed){var rows=ParseAiRows(response);int applied=0;foreach(var group in rows.Where(r=>allowed.Contains(r["id"])).GroupBy(r=>r["id"])){var app=packages.FirstOrDefault(a=>a.Id==group.Key);if(app==null)continue;applied++;var row=group.FirstOrDefault(r=>r["risk"]!="low")??group.First();app.AiOpinion="AI 意见："+row["reason"]+"；来源：AI/本地 Agent 推断；实际依赖未经验证。";if(IsCore(app.Id)||row["risk"]=="high"){app.Risk="疑似系统组件";app.AiOpinion="【疑似系统组件】"+app.AiOpinion+" 此意见仅供参考；卸载可能导致电视失效。";app.Reason=app.AiOpinion+" 仅供人工复核；不建议操作。";continue;}if(app.State!="已安装"){app.Risk="谨慎卸载";app.AiOpinion="【当前非已安装状态】"+app.AiOpinion+" 无需重复卸载，请先核对状态。";continue;}app.Risk=row["risk"]=="low"&&app.Path.StartsWith("/data/app/")?"推荐卸载":"谨慎卸载";app.AiOpinion="【"+app.Risk+"】"+app.AiOpinion;app.Reason="依据："+row["reason"]+"；来源：AI 推断；不确定性：实际依赖未经验证，请人工复核。";}if(applied==0)throw new Exception("AI 返回的包名与当前批次不匹配，未采用建议。");}
}
